#!/bin/zsh
# 让 Codex 出两张图：录音列表的新行样式（标题 + 小信息，不放正文），和录完之后的「留着 / 不要」提示。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "请使用内置的 image_gen 工具生成一张 16:10 横向的高保真 UI 设计稿（像设计师在 Figma 里做的最终稿截图，正视图、不要透视）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="产品是一款 macOS 桌面应用「豆仓」：连接一颗 AI 录音豆，把录音自动转成文字、整理成纪要和待办。设计语言：苹果 macOS 最新风格加乔纳森·艾维式的克制——留白舒服、字号层级清晰、对齐严谨、圆角统一。配色严格限定：暖白纸色背景（#F6F3EC）、石墨黑文字（#1A1A1A）、唯一强调色琥珀橙（#F2A33A），红色（#F0453A）只用于录音按钮和「不要了」这类删除动作；绝对不要蓝色、紫色、青色。界面文字全部是简体中文，字体像苹方，清晰可读、没有乱码。窗口是带红黄绿三个圆点的 macOS 窗口，左侧窄侧栏：顶部豆仓小图标和名字、一个红色胶囊按钮「开始录音」、导航三项「总览」「录音」「知识库」（录音选中）、底部小卡片「soundcore Work · 已连接 · 100%」。"
gen ui_list_rows "【录音页，重点是中间的录音列表】列表顶部是搜索框和一排筛选「全部 / 星标 / 有待办 / 有重点」，下面按「今天」「昨天」分组。每一行录音只有三样东西，不放任何正文或摘要句子：① 左边一个琥珀色的场景小图标方块；② 一行粗体标题，是 AI 总结出来的一句话，例如「周会确定新品发布时间与汇款率排查」「吐槽录音功能设计：按钮重复与空白大页面」「策划黄仁勋卸任一分钟口播视频脚本」；③ 标题下面一行很小的灰色信息，由几个小元素横排组成：时间「16:52」、时长「0:44」、场景「会议」，后面跟着两三个浅琥珀色底的小胶囊关键词，例如「发布时间」「汇款率」，再后面是小图标加数字，例如一个勾选框图标「3」表示三个待办、一面小旗「2」表示两个重点、一颗实心星表示星标。第一行是选中状态（浅琥珀底）。其中一行正在被右键点开，旁边浮着一个 macOS 原生样式的右键菜单，菜单项依次是：「重命名…」「让 AI 重新起标题」「标为星标」「拷贝文字稿」分隔线「从这台 Mac 删除…」「从录音豆删除…」（最后两项是红字）。右边一列是这条录音的详情（大标题、三个页签「纪要 / 文字稿 / 改写」、摘要卡片），可以简单画。$S" &
gen ui_after_record "【刚录完一条录音的那一刻】主界面是总览页（左上小仓鼠吉祥物和大号问候「下午好」，下面是待办和最近的录音，画得淡一些作为背景）。重点是窗口正中偏上浮着一张精致的小卡片（圆角 20、细腻阴影、暖白底），宽度约占窗口三分之一：卡片左边是一个琥珀色的小波形图标，旁边粗体「录好了」和小灰字「0:25 · 来自 soundcore Work」；下面一行小灰字「留着的话，会自动转成文字并整理成纪要。」；卡片底部并排两个按钮：左边是次要的文字按钮「不要这条」（红字、无底色），右边是琥珀色的主按钮「留着」。卡片底部有一条很细的琥珀色进度线，表示几秒后不选就默认留着，旁边极小的灰字「10 秒后自动留着」。$S" &
wait
